  }
}

function taskAction(event) {
  const control = event.target.closest('[data-action]');
  if (!control) return;
  if (control.dataset.action === 'toggle' && event.type !== 'change') return;
  if (control.dataset.action !== 'toggle' && event.type !== 'click') return;
  const card = control.closest('[data-task-id]');
  const task = tasks.find(candidate => candidate.id === card?.dataset.taskId);
  if (!task) return;
  if (control.dataset.action === 'toggle') {
    const nextTask = setTaskCompleted(task, control.checked);
    if (persist(tasks.map(candidate => candidate.id === task.id ? nextTask : candidate))) {
      render();
      showFeedback(nextTask.completed ? 'Task completed.' : 'Task reopened.');
    } else control.checked = task.completed;
  }
  if (control.dataset.action === 'edit') openTaskDialog(task, control);
  if (control.dataset.action === 'delete') openDeleteDialog(task, control);
}

elements.newTask.addEventListener('click', event => openTaskDialog(null, event.currentTarget));
elements.emptyAction.addEventListener('click', event => {
  if (elements.clearFilters.hidden) openTaskDialog(null, event.currentTarget);
  else {
    elements.search.value = '';
    elements.status.value = 'all';
    elements.priority.value = 'all';
    render();
  }
});
elements.closeDialog.addEventListener('click', closeTaskDialog);
elements.cancelDialog.addEventListener('click', closeTaskDialog);
elements.form.addEventListener('submit', saveForm);
elements.taskList.addEventListener('click', taskAction);
elements.taskList.addEventListener('change', taskAction);
for (const element of [elements.search, elements.status, elements.priority]) element.addEventListener('input', render);
elements.clearFilters.addEventListener('click', () => {
  elements.search.value = '';
  elements.status.value = 'all';
  elements.priority.value = 'all';
  render();
  elements.search.focus();
});
elements.cancelDelete.addEventListener('click', closeDeleteDialog);
elements.deleteForm.addEventListener('submit', event => {
  event.preventDefault();
  const task = tasks.find(candidate => candidate.id === deletingTaskId);
  if (!task) { setNotice(elements.deleteError, 'This task is no longer available.'); return; }
  if (!persist(tasks.filter(candidate => candidate.id !== task.id))) {
    setNotice(elements.deleteError, 'The task could not be deleted. Please try again.');
    return;
  }
  closeDeleteDialog();
  render();
  showFeedback('Task deleted.');
});
for (const dialog of [elements.taskDialog, elements.deleteDialog]) {
  dialog.addEventListener('cancel', () => { window.setTimeout(() => opener?.focus(), 0); });
}

elements.today.textContent = new Intl.DateTimeFormat('en-US', { weekday: 'long', month: 'long', day: 'numeric' }).format(new Date());
setNotice(elements.storageError, storageState.message);
for (const control of [elements.newTask, elements.emptyAction]) control.disabled = !storageState.writable;
render();
import test from 'node:test';
import assert from 'node:assert/strict';
import { createTask, editTask, filterTasks, formatDueDate, isLocalDate, setTaskCompleted, validateInput } from '../src/domain.js';

const input = { title: ' Draft plan ', notes: 'First outline', priority: 'High', dueDate: '2026-10-03', estimatedMinutes: 45 };

test('creates a normalized task with complete metadata', () => {
  const task = createTask(input, { id: 'task-1', now: '2026-09-24T12:00:00.000Z' });
  assert.deepEqual(task, { id: 'task-1', title: 'Draft plan', notes: 'First outline', priority: 'High', dueDate: '2026-10-03', estimatedMinutes: 45, completed: false, createdAt: '2026-09-24T12:00:00.000Z', updatedAt: '2026-09-24T12:00:00.000Z' });
});

test('validates required and bounded task fields', () => {
  const result = validateInput({ title: '', notes: 'x'.repeat(2001), priority: 'Urgent', dueDate: '2026-02-29', estimatedMinutes: 4 });
  assert.deepEqual(Object.keys(result.errors).sort(), ['dueDate', 'estimatedMinutes', 'notes', 'priority', 'title']);
  assert.equal(isLocalDate('2024-02-29'), true);
  assert.equal(isLocalDate('2026-02-29'), false);
});

test('edits and changes completion without losing task identity', () => {
  const original = createTask(input, { id: 'task-2', now: '2026-09-24T12:00:00.000Z' });
  const edited = editTask(original, { ...input, title: 'Revised plan', priority: 'Low' }, '2026-09-25T12:00:00.000Z');
  const completed = setTaskCompleted(edited, true, '2026-09-26T12:00:00.000Z');
  assert.equal(completed.id, 'task-2');
  assert.equal(completed.createdAt, original.createdAt);
  assert.equal(completed.title, 'Revised plan');
  assert.equal(completed.completed, true);
  assert.equal(completed.updatedAt, '2026-09-26T12:00:00.000Z');
});

test('searches titles and combines status and priority filters', () => {
  const tasks = [
    createTask(input, { id: '1', now: '2026-09-24T12:00:00.000Z' }),
    { ...createTask({ ...input, title: 'Read brief', priority: 'Low' }, { id: '2', now: '2026-09-24T12:00:00.000Z' }), completed: true },
    createTask({ ...input, title: 'Draft email', priority: 'Medium' }, { id: '3', now: '2026-09-24T12:00:00.000Z' })
  ];
  assert.deepEqual(filterTasks(tasks, { search: 'DRAFT', status: 'open', priority: 'Medium' }).map(task => task.id), ['3']);
  assert.deepEqual(filterTasks(tasks, { status: 'completed' }).map(task => task.id), ['2']);
  assert.equal(formatDueDate('2026-10-03'), 'Oct 3, 2026');
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { createTask } from '../src/domain.js';
import { loadTasks, saveTasks, STORAGE_KEY, STORAGE_VERSION } from '../src/storage.js';

function memoryStorage(initial = {}) {
  const values = new Map(Object.entries(initial));
  return { getItem: key => values.get(key) ?? null, setItem: (key, value) => values.set(key, value), values };
}

const task = createTask({ title: 'Review brief', notes: '', priority: 'Medium', dueDate: null, estimatedMinutes: 25 }, { id: 'task-1', now: '2026-09-24T12:00:00.000Z' });

test('saves a versioned record and restores valid tasks', () => {
  const storage = memoryStorage();
  assert.deepEqual(saveTasks(storage, [task]), { ok: true, message: '' });
  assert.deepEqual(loadTasks(storage), { tasks: [task], writable: true, message: '' });
  assert.equal(JSON.parse(storage.values.get(STORAGE_KEY)).version, STORAGE_VERSION);
});

test('preserves damaged or unsupported data by disabling editing', () => {
  const damaged = loadTasks(memoryStorage({ [STORAGE_KEY]: '{not json' }));
  const unsupported = loadTasks(memoryStorage({ [STORAGE_KEY]: JSON.stringify({ version: 99, tasks: [] }) }));
  assert.equal(damaged.writable, false);
  assert.match(damaged.message, /damaged/);
  assert.equal(unsupported.writable, false);
  assert.match(unsupported.message, /unsupported/);
});

test('skips invalid records without overwriting valid stored data', () => {
  const storage = memoryStorage({ [STORAGE_KEY]: JSON.stringify({ version: STORAGE_VERSION, tasks: [task, { ...task, id: 'task-1' }, { id: 'bad' }] }) });
  const loaded = loadTasks(storage);
  assert.deepEqual(loaded.tasks, [task]);
  assert.equal(loaded.writable, false);
  assert.match(loaded.message, /invalid or duplicate/);
});

test('reports storage write failures', () => {
  const storage = { getItem: () => null, setItem: () => { throw new Error('blocked'); } };
  assert.deepEqual(saveTasks(storage, [task]), { ok: false, message: 'Could not save to this browser. Storage may be full or blocked. No changes were applied. Your form is kept open so you can retry.' });
});
